-- KUERA Cloud Migration Script
-- Generated: 2026-04-02T12:35:40.997381
-- Source: SQLite Local
-- Target: PostgreSQL Cloud

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Create tables

-- Table: interactions

                CREATE TABLE interactions (
                    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
                    user_id TEXT NOT NULL,
                    user_message TEXT NOT NULL,
                    ai_response TEXT NOT NULL,
                    intent TEXT,
                    sentiment TEXT,
                    confidence REAL DEFAULT 0.0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    session_id TEXT,
                    metadata JSONB DEFAULT '{{}}'
                );
                CREATE INDEX idx_interactions_user ON interactions(user_id);
                CREATE INDEX idx_interactions_time ON interactions(created_at);
            

-- Table: user_profiles

                CREATE TABLE user_profiles (
                    user_id TEXT PRIMARY KEY,
                    name TEXT,
                    province TEXT,
                    language TEXT DEFAULT 'id',
                    age_group TEXT,
                    gender TEXT,
                    occupation TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    last_active TIMESTAMP,
                    metadata JSONB DEFAULT '{{}}'
                );
            

-- Table: model_metrics

                CREATE TABLE model_metrics (
                    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
                    model_name TEXT NOT NULL,
                    f1_score REAL,
                    accuracy REAL,
                    training_samples INTEGER,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    metadata JSONB DEFAULT '{{}}'
                );
            

-- Table: sessions

                CREATE TABLE sessions (
                    session_id TEXT PRIMARY KEY,
                    user_id TEXT NOT NULL,
                    start_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    end_time TIMESTAMP,
                    messages_count INTEGER DEFAULT 0,
                    metadata JSONB DEFAULT '{{}}'
                );
            

-- Table: knowledge_base

                CREATE TABLE knowledge_base (
                    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
                    topic TEXT NOT NULL,
                    subtopic TEXT,
                    content TEXT NOT NULL,
                    language TEXT DEFAULT 'id',
                    province TEXT,
                    priority INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
            

-- Table: analytics_daily

                CREATE TABLE analytics_daily (
                    date DATE PRIMARY KEY,
                    total_interactions INTEGER DEFAULT 0,
                    unique_users INTEGER DEFAULT 0,
                    avg_confidence REAL DEFAULT 0.0,
                    satisfaction_score REAL DEFAULT 0.0
                );
            

-- Table: sync_status

                CREATE TABLE sync_status (
                    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
                    last_sync TIMESTAMP,
                    sync_type TEXT,
                    status TEXT,
                    records_synced INTEGER DEFAULT 0
                );
            

-- Insert data into interactions

-- Create views
CREATE OR REPLACE VIEW daily_stats AS
SELECT 
    DATE(created_at) as date,
    COUNT(*) as total_interactions,
    COUNT(DISTINCT user_id) as unique_users,
    AVG(confidence) as avg_confidence
FROM interactions
GROUP BY DATE(created_at);

-- Migration complete
VALUES (CURRENT_TIMESTAMP, 'initial_migration', 'completed', 0);
